tape( 'the function performs matrix-vector operation `y = alpha*A*x + beta*y` where `alpha` and `beta` are scalars, `x` and `y` are `N` element vectors, and `A` is an `N` by `N` symmetric band matrix, with `K` super-diagonals (row-major, lower)', function test( t ) {
	var expected;
	var out;
	var a;
	var x;
	var y;

	a = new Float32Array( rl.A );
	x = new Float32Array( rl.x );
	y = new Float32Array( rl.y );

	expected = new Float32Array( rl.y_out );

	out = ssbmv( rl.order, rl.uplo, rl.N, rl.K, rl.alpha, a, rl.LDA, x, rl.strideX, rl.beta, y, rl.strideY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

