tape( 'if `N` is zero or the scalar constants are zero and unity, respectively, the function returns the second input vector unchanged (row-major)', function test( t ) {
	var expected;
	var out;
	var a;
	var x;
	var y;

	a = new Float32Array( rl.A );
	x = new Float32Array( rl.x );
	y = new Float32Array( rl.y );

	expected = new Float32Array( rl.y );

	out = ssbmv( rl.order, rl.uplo, 0, rl.K, rl.alpha, a, rl.LDA, x, rl.strideX, rl.beta, y, rl.strideY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	out = ssbmv( rl.order, rl.uplo, rl.N, rl.K, 0.0, a, rl.LDA, x, rl.strideX, 1.0, y, rl.strideY );
	t.strictEqual( out, y, 'returns expected value' );
	t.deepEqual( y, expected, 'returns expected value' );

	t.end();
});

